import{_ as l,o,c as i,a5 as n}from"./chunks/framework.Cooo9kuv.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"847-便捷视频剪切-视频片段删除合并工具V1.0","日期":"2026-04-14T00:00:00.000Z","修改日期":"2026-04-14T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["音频视频批处理"],"标签":["图形化界面","快速剪辑","桌面工具","视频剪切","视频编辑"]},"headers":[],"relativePath":"md/音频视频批处理/847-便捷视频剪切-视频片段删除合并工具V1.0.md","filePath":"md/音频视频批处理/847-便捷视频剪切-视频片段删除合并工具V1.0.md"}'),r={name:"md/音频视频批处理/847-便捷视频剪切-视频片段删除合并工具V1.0.md"};function a(s,t,e,g,p,u){return o(),i("div",null,[...t[0]||(t[0]=[n('<p>对单个视频文件进行剪辑操作，删除视频中的1个片段或多个片段，删除多个片段后自动合并未删除的视频片段，生成的视频为标准H264编码格式的mp4格式视频。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251204211503176485410348018.png" alt=""></p><h3 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to &quot;核心功能&quot;">​</a></h3><ul><li><strong>视频播放与预览</strong>：拖入视频播放预览</li><li><strong>区间标记</strong>：可视化标记需要保留或删除的视频片段</li><li><strong>片段管理</strong>：支持添加、删除、修改剪切区间</li><li><strong>灵活的剪切模式</strong>：支持删除标记区间或保留标记区间两种模式</li><li><strong>批量处理</strong>：支持同时处理多个视频片段，</li><li><strong>硬件加速</strong>：自动检测并使用 NVIDIA NVENC、Intel QSV、AMD AMF 等硬件加速技术</li><li><strong>关键帧对齐</strong>：自动将剪切点对齐到视频关键帧，减少音画不同步问题</li><li><strong>支持的视频格式：</strong>&#39;.mp4&#39;, &#39;.avi&#39;, &#39;.mkv&#39;, &#39;.mov&#39;, &#39;.ts&#39;, &#39;.flv&#39;, &#39;.wmv&#39;, &#39;.m4v&#39;, &#39;.webm&#39;</li><li>**比较友好的视频格式：**mp4、avi、mkv</li></ul><h3 id="基本操作流程" tabindex="-1">基本操作流程 <a class="header-anchor" href="#基本操作流程" aria-label="Permalink to &quot;基本操作流程&quot;">​</a></h3><ol><li><strong>打开视频文件</strong><ul><li>点击&quot;打开&quot;按钮选择要处理的视频文件</li><li>或直接将视频文件拖放到程序窗口</li></ul></li><li><strong>预览视频</strong><ul><li>使用播放/暂停按钮控制视频播放</li><li>拖动时间轴滑块快速定位</li><li>查看当前时间和总时长</li></ul></li><li><strong>标记剪切区间</strong><ul><li>设置起始时间和结束时间</li><li>点击&quot;添加剪切区间&quot;按钮标记区间</li><li>重复此步骤标记多个区间</li></ul></li><li><strong>管理剪切区间</strong><ul><li>在区间列表中查看所有标记的区间</li><li>右键点击区间可选择： <ul><li>标记为要删除</li><li>标记为要保留</li><li>取消标记</li><li>从列表中移除</li></ul></li></ul></li><li><strong>设置剪切模式</strong><ul><li>勾选&quot;删除标记区间&quot;选项：删除所有标记的区间</li><li>取消勾选：仅保留所有标记的区间</li></ul></li><li><strong>执行剪切操作</strong><ul><li>选择输出目录</li><li>点击&quot;开始剪切&quot;按钮</li><li>等待处理完成（可随时取消）</li><li>处理完成后，在输出目录查看结果文件</li></ul></li></ol><h3 id="程序截图" tabindex="-1">程序截图 <a class="header-anchor" href="#程序截图" aria-label="Permalink to &quot;程序截图&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251204171257176483957750002.jpg" alt=""></p><h3 id="程序使用环境及相关说明" tabindex="-1">程序使用环境及相关说明 <a class="header-anchor" href="#程序使用环境及相关说明" aria-label="Permalink to &quot;程序使用环境及相关说明&quot;">​</a></h3><blockquote><p><strong>1、适用的系统环境说明</strong>： win7及以上64位win操作系统 ，  **注意事项：**win32位系统以及mac系统需要额外定制开发</p><p><strong>2、关于使用限制</strong>：①无需注册、登录等限制，直接使用，  ②没有电脑台数限制，  ③无使用时间限制、不联网本地使用、确保数据安全</p><p><strong>3、程序如何安装</strong>：不需要安装，按照说明使用即可。</p><p><strong>特别注意</strong>：请先测试，注意备份原文件，之后再批量使用，避免不可逆损失。</p></blockquote><h3 id="程序使用说明" tabindex="-1">程序使用说明 <a class="header-anchor" href="#程序使用说明" aria-label="Permalink to &quot;程序使用说明&quot;">​</a></h3><p><strong>第一步：先将apitool文件夹复制到C盘根目录下，如下图所示：</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251010144245176007856553033-6.jpg" alt=""></p><p><strong>第二步：双击快捷方式使用即可，快捷方式可以放到桌面，或其他地方使用，第一个文件夹名及文件夹内内容修改后会导致程序无法正确运行</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251204212001176485440126683.png" alt=""></p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2193.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2193.html</a></p>',17)])])}const m=l(r,[["render",a]]);export{c as __pageData,m as default};
